css:
:scope{--ink:var(--os-color-text);--ink-soft:#2D4F51;--teal:#0F5457;--rose:var(--os-color-accent);--serif:'Cormorant Garamond', Georgia, serif;--sans:'Jost', system-ui, sans-serif}
:scope{color:var(--ink);font-family:var(--sans);font-weight:300;font-size:18px;line-height:1.75}
@media (max-width:767px){:scope{font-size:17px}}
:where(h1,h2,h3,h4,h5,h6){color:inherit;font-family:inherit;font-weight:bold;font-style:inherit;letter-spacing:normal;text-transform:none;line-height:inherit;text-wrap:wrap}
:where(h1){font-size:2em}:where(h2){font-size:1.5em}:where(h3){font-size:1.17em}:where(h4){font-size:1em}:where(h5){font-size:.83em}:where(h6){font-size:.67em}
:where(.os-ci){display:inline-block;max-width:100%;vertical-align:middle;aspect-ratio:auto}
.os-ci>picture{display:contents}
.os-ci img{display:block;width:100%;height:100%;object-fit:inherit;object-position:inherit;border-radius:inherit}
*{box-sizing:border-box}
h2,h3{font-family:var(--serif);font-weight:300;margin:0;line-height:1.08;color:var(--teal)}
p{margin:0}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
.gold-text{background:linear-gradient(100deg,#B8862E 0%,#F6E2A8 38%,#D8B160 60%,#9E7425 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.eyebrow{font-size:14px;letter-spacing:.34em;text-transform:uppercase;color:var(--rose);font-weight:400}
section{padding:100px 0}
.center{text-align:center;display:flex;flex-direction:column;gap:14px;align-items:center}
.center h2{font-size:clamp(40px,5vw,64px)}
.journey{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:44px;margin-top:48px}
.journey > div{display:flex;flex-direction:column;gap:12px;align-items:center;text-align:center}
.journey .num{font-family:var(--serif);font-size:68px;line-height:1}
.journey h3{font-size:28px;font-weight:500}
.journey p{font-size:17px;color:var(--ink-soft)}
@media (max-width:767px){section{padding:72px 0}}
